function appendEnglishGrammarItems(rows) {
  GRAMMAR_DB.push(...rows.map(([lv, q, choices, ans, exp], idx) => ({
    id: `g${String(GRAMMAR_DB.length + idx + 1).padStart(3, '0')}`,
    lv, q, choices, ans, exp,
  })));
}

