/* ══════════════════════════════════════════════════
   ビジネス・経済クイズ（有名企業・産業・起業家・会計・税制）
   学習中の言語圏の経済事情について、日本語で出題する4択トリビア
══════════════════════════════════════════════════ */
function businessItems(code, rows) {
  return rows.map(([lv, q, choices, ans, exp], idx) => ({
    id: `${code}b${String(idx + 1).padStart(3, '0')}`,
    lv, q, choices, ans, exp,
  }));
}

